/**
 * The Opace AI Content Checker & Detector product mark, embedded so every report is self-contained.
 *
 * Both derivatives come from the canonical repository asset
 * docs/assets/opace-ai-content-checker-detector-logo-v3.png
 * (SHA-256 cee92ccc36ae18bef908fa536f370792b4034b6d0446b18b83a028ac12a42e37, 1024 x 1024).
 *
 * - LOGO_PNG_96_BASE64:  96 x 96 PNG,  used as a data URI in the printable HTML report.
 * - LOGO_JPEG_128_BASE64: 128 x 128 JPEG, used as a DCTDecode XObject in the PDF, because
 *   PDF 1.4 embeds JPEG natively and needs no decoder.
 *
 * Regenerate with:
 *   sips -Z 96 --setProperty format png <source> --out assets/opace-logo-96.png
 *   sips -Z 128 --setProperty format jpeg --setProperty formatOptions 82 <source> --out assets/opace-logo-128.jpg
 */

export const LOGO_PNG_96_BASE64 =
  '';

export const LOGO_JPEG_128_BASE64 =
  '';

/** Ready-to-use data URI for the printable HTML report. */
export const LOGO_PNG_96_DATA_URI = `data:image/png;base64,${LOGO_PNG_96_BASE64}`;

const LOOKUP = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** Decode base64 to bytes without atob or Buffer, so the module runs anywhere. */
export function decodeBase64(value) {
  const clean = String(value).replace(/[^A-Za-z0-9+/]/gu, '');
  const bytes = new Uint8Array(Math.floor((clean.length * 3) / 4));
  let cursor = 0;
  let buffer = 0;
  let bits = 0;
  for (const character of clean) {
    buffer = (buffer << 6) | LOOKUP.indexOf(character);
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes[cursor] = (buffer >> bits) & 0xff;
      cursor += 1;
    }
  }
  return bytes.subarray(0, cursor);
}

/** The PDF header logo as JPEG bytes. */
export const logoJpegBytes = () => decodeBase64(LOGO_JPEG_128_BASE64);
